with ranked as (select *, row_number() over (partition by txn_type order by amount nulls last, id) as rank_in_group from transactions qualify rank_in_group = 1) select id, txn_type, amount, merchant, rank_in_group, case when merchant rlike '^(Lazada|7-Eleven)$' then 'EXTENDED' when merchant rlike '^(Grab|Amazon)$' then 'GROUP_B' else 'OTHER_ZONE' end as merchant_zone from ranked order by merchant desc nulls first;
